(()=>{

'use strict';
const GRID=9,SIZE=640,canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),frame=document.querySelector('.frame'),status=document.getElementById('status'),save=document.getElementById('save');
let ready=false,mx=.5,my=.5,tx=.5,ty=.5,raf=0,pointer=null,px=0,py=0,sx=.5,sy=.5,tiltEnabled=false,ag=null,ab=null,ax=.5,ay=.5,lastG=null,lastB=null;
const viewImage=new Image();
viewImage.onload=()=>{ready=true;save.disabled=false;status.textContent='Preview ready · drag to move the light';schedule();};
viewImage.onerror=()=>{status.textContent='The preview could not load. Reload this page to retry.';};
viewImage.src='data:image/webp;base64,';
const clamp=v=>Math.max(0,Math.min(1,v));
function draw(){
 raf=0;if(!ready||document.hidden||!ctx)return;
 mx+=(tx-mx)*.15;my+=(ty-my)*.15;
 const x=mx*(GRID-1),y=(1-my)*(GRID-1),ix=Math.floor(x),iy=Math.floor(y),dx=x-ix,dy=y-iy;
 ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;ctx.fillStyle='#000';ctx.fillRect(0,0,SIZE,SIZE);
 ctx.globalCompositeOperation='lighter';
 for(let j=0;j<2;j++)for(let i=0;i<2;i++){
  const weight=(i?dx:1-dx)*(j?dy:1-dy);if(!weight)continue;
  ctx.globalAlpha=weight;ctx.drawImage(viewImage,Math.min(ix+i,GRID-1)*SIZE,Math.min(iy+j,GRID-1)*SIZE,SIZE,SIZE,0,0,SIZE,SIZE);
 }
 ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;
 if(Math.abs(tx-mx)+Math.abs(ty-my)>.0002){schedule();document.getElementById('saveSurface').hidden=true;}else if(pointer===null){const surface=document.getElementById('saveSurface');surface.src=canvas.toDataURL('image/png');surface.hidden=false;}
}
function schedule(){if(ready&&!document.hidden&&!raf)raf=requestAnimationFrame(draw);}
function point(e){const r=frame.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:1-(e.clientY-r.top)/r.height};}
function release(){const old=pointer;pointer=null;if(old!==null){try{frame.releasePointerCapture(old);}catch(_){}}ag=lastG;ab=lastB;ax=tx;ay=ty;schedule();}
frame.addEventListener('pointerdown',e=>{if(pointer!==null||e.isPrimary===false)return;pointer=e.pointerId;try{frame.setPointerCapture(pointer);}catch(_){release();return;}const p=point(e);px=p.x;py=p.y;sx=tx;sy=ty;});
frame.addEventListener('pointermove',e=>{if(e.pointerId!==pointer)return;const p=point(e);if(Math.abs(p.x-px)+Math.abs(p.y-py)>.008)document.getElementById('saveSurface').hidden=true;tx=clamp(sx+p.x-px);ty=clamp(sy+p.y-py);schedule();});
for(const n of ['pointerup','pointercancel','lostpointercapture'])frame.addEventListener(n,e=>{if(e.pointerId===pointer)release();});
document.getElementById('tilt').addEventListener('click',async()=>{
 try{if(typeof DeviceOrientationEvent==='undefined'){status.textContent='Tilt unavailable here · dragging still works';return;}
 if(typeof DeviceOrientationEvent.requestPermission==='function'&&await DeviceOrientationEvent.requestPermission()!=='granted'){status.textContent='Tilt permission was not granted · dragging still works';return;}
 tiltEnabled=true;ag=ab=null;status.textContent='Tilt enabled · dragging also works';}catch(_){status.textContent='Tilt could not start · dragging still works';}
});
window.addEventListener('deviceorientation',e=>{if(!tiltEnabled||document.hidden||!Number.isFinite(e.gamma)||!Number.isFinite(e.beta))return;lastG=e.gamma;lastB=e.beta;if(pointer!==null)return;if(ag===null||ab===null){ag=e.gamma;ab=e.beta;ax=tx;ay=ty;return;}tx=clamp(ax+(e.gamma-ag)/70);ty=clamp(ay+(e.beta-ab)/70);schedule();});
save.addEventListener('click',()=>{if(!ready)return;const uri=canvas.toDataURL('image/png');document.getElementById('snapshot').src=uri;document.getElementById('download').href=uri;document.getElementById('savePanel').hidden=false;status.textContent='Snapshot ready below · hologram pixels only';});
function suspend(){release();ag=ab=null;if(raf)cancelAnimationFrame(raf);raf=0;}
document.addEventListener('visibilitychange',()=>{if(document.hidden)suspend();else{ag=ab=null;schedule();}});window.addEventListener('pagehide',suspend);window.addEventListener('pageshow',()=>{ag=ab=null;schedule();});

frame.addEventListener('contextmenu',()=>{tiltEnabled=false;release();const surface=document.getElementById('saveSurface');surface.src=canvas.toDataURL('image/png');surface.hidden=false;status.textContent='View paused for saving · drag or enable tilt to continue';});

})();